import requests
from bs4 import BeautifulSoup

# 初始化Google搜索的URL模板
def google_search_query(query):
    return f"https://www.google.com/search?q={query}"

# 获取页面内容
def get_page_content(url):
    headers = {'User-Agent': 'Mozilla/5.0 (X11; Ubuntu; Linux x86_64; rv:85.0) Gecko/20100101 Firefox/85.0'}
    response = requests.get(url, headers=headers)
    if response.status_code == 200:
        return response.text
    else:
        print(f"Failed to retrieve {url}")
        return None

# 解析搜索结果并获取URL列表
def parse_search_results(html):
    soup = BeautifulSoup(html, 'html.parser')
    links = []
    for a_tag in soup.find_all('a', href=True):
        link = a_tag['href']
        if "http" in link:
            links.append(link)
    return links

# Google Dork查询
def google_dork(query):
    html = get_page_content(google_search_query(query))
    if html:
        return parse_search_results(html)
    else:
        return []

# 主函数，用于批量扫描目标网站
def scan_target 网站(dork_queries, depth=1):
    found_urls = set()

    for query in dork_queries:
        urls = google_dork(query)
        for url in urls:
            if url not in found_urls and "http" in url:
                print(f"Checking {url}")
                # 在这里可以添加更多的检查，比如文件类型或特定字符串的搜索
                found_urls.add(url)

    return list(found_urls)

# 示例使用Google Dork查询来扫描可能暴露敏感信息的网站
if __name__ == "__main__":
    queries = [
        "site:example.com intitle:index of secret",
        "site:example.com intitle:login admin"
    ]
    targets = scan_target("example.com", queries)
    print("Found URLs:")
    for target in targets:
        print(target)
```

