由于我无法直接安装或运行代码来分析实际的电子邮件头部信息，我将提供一个Python脚本的概念性示例，该脚本可以用来提取邮件头中的内部IP地址和服务器配置信息。请注意，这个脚本仅作为演示，实际使用时需要根据具体情况进行调整。

```python
import re
from email.utils import parseheaders

# 正则表达式用于匹配IPv4和IPv6地址
ipv4_pattern = re.compile(r'\b(?:\d{1,3}\.){3}\d{1,3}\b')
ipv6_pattern = re.compile(r'('
                           r'([0-9a-fA-F]{1,4}:){7}([0-9a-fA-F]{1,4})|'
                           r'([0-9a-fA-F]{1,4}:){6}:[0-9a-fA-F]{1,4}|'
                           r'([0-9a-fA-F]{1,4}:){5}(:[0-9a-fA-F]{1,4}){1,2}|'
                           r'([0-9a-fA-F]{1,4}:){4}(:[0-9a-fA-F]{1,4}){1,3}|'
                           r'([0-9a-fA-F]{1,4}:){3}(:[0-9a-fA-F]{1,4}){1,4}|'
                           r'([0-9a-fA-F]{1,4}:){2}(:[0-9a-fA-F]{1,4}){1,5}|'
                           r'([0-9a-fA-F]{1,4}:){1}(:[0-9a-fA-F]{1,4}){1,6}|'
                           r'::(:[0-9a-fA-F]{1,4}){1,7}'
                           r')', re.VERBOSE)

# 正则表达式用于匹配MX记录和SPF设置
mx_pattern = re.compile(r'MX\s*:\s*(\S+)')
spf_pattern = re.compile(r'SPF\s*:\s*(\S+)')

def extract_internal_ips(email_header):
    internal_ips = []
    for header in email_header:
        if 'Received' in header[0]:
            headers = parseheaders(header[1])
            for h in headers:
                if h[0].lower() == 'received':
                    for ip in ipv4_pattern.findall(h[1]):
                        if ip not in internal_ips and not ip.startswith('127.'):
                            internal_ips.append(ip)
                    for ip in ipv6_pattern.findall(h[1]):
                        if ip not in internal_ips:
                            internal_ips.append(ip)
    return list(set(internal_ips))

def extract_server_config(email_header):
    server_config = {}
    for header in email_header:
        if 'from' in header[0]:
            headers = parseheaders(header[1])
            for h in headers:
                if h[0].lower() == 'from':
                    domain = re.findall(r'\S+@[^\s]+', h[1])[0].split('@')[1]
                    server_config['domain'] = domain
        elif 'mx' in header[0]:
            headers = parseheaders(header[1])
            for h in headers:
                if h[0].lower() == 'mx':
                    mx_records = mx_pattern.findall(h[1])
                    server_config['mx_records'] = mx_records
        elif 'spf' in header[0]:
            headers = parseheaders(header[1])
            for h in headers:
                if h[0].lower() == 'spf':
                    spf_settings = spf_pattern.findall(h[1])[0]
                    server_config['spf'] = spf_settings
    return server_config

def analyze_email_header(email_headers):
    internal_ips = extract_internal_ips(email_headers)
    server_config = extract_server_config(email_headers)

    # Output the results
    print("Internal IPs:", internal_ips)
    print("Server Configuration:", server_config)

# 示例电子邮件头部信息
email_headers = [
    ("Received", "from [10.0.0.1] by mail.example.com with SMTP id ..."),
    ("From", "user@example.com"),
    ("MX", "mail.example.com EXACT"),
    ("SPF", "v=spf1 a -all")
]

analyze_email_header(email_headers)
```

