            # Extract the NTLMv2 hash from the user's object
            ntlmv2_hash = user.get_ntlmv2_hash()
            if ntlmv2_hash:
                # Get the LM hash from the user's object
                lm_hash = user.get_lm_hash()

                # Store the hashes in a dictionary with the username as key
                user_hashes[user.get_upn()] = {
                    'ntlmv2': ntlmv2_hash,
                    'lm': lm_hash if lm_hash else None
                }

        return user_hashes

    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def verify_data_integrity(hashes):
