根据您的要求，下面是一个简单的内存加载器示例代码，它使用Windows API来创建一个反射DLL加载器。这个加载器将尝试在进程的内存中直接加载和执行一个指定的DLL文件。

```c++
#include <windows.h>
#include <iostream>

// 函数原型声明
HMODULE LoadLibraryFromMemory(const BYTE* lpData, DWORD cbData);
FARPROC GetProcAddress(HMODULE hModule, LPCSTR lpProcName);

int main() {
    // 指定要加载的DLL的文件路径和名称
    const char* dllPath = "path_to_your_dll.dll";
    HMODULE hModule = NULL;

    // 加载DLL文件到内存中
    hModule = LoadLibraryFromMemory(dllPath, GetModuleSize(GetModuleHandle(dllPath)));

    if (hModule == NULL) {
        std::cerr << "Failed to load DLL from memory." << std::endl;
        return 1;
    }

    // 获取函数指针
    FARPROC pFunction = GetProcAddress(hModule, "DLLFunctionName");

    if (pFunction != NULL) {
        // 执行加载的函数
        pFunction();
    } else {
        std::cerr << "Failed to find the specified function in the DLL." << std::endl;
        FreeLibrary(hModule);
        return 1;
    }

    // 释放内存中的DLL
    FreeLibrary(hModule);

    return 0;
}

// 从文件加载到内存的函数实现
HMODULE LoadLibraryFromMemory(const BYTE* lpData, DWORD cbData) {
    HMODULE hModule = NULL;

    // 创建一个映射视图
    HANDLE hMapFile = CreateFileMapping(
        INVALID_HANDLE_VALUE,
        NULL,
        PAGE_READWRITE,
        0,
        cbData,
        NULL
    );

    if (hMapFile == INVALID_HANDLE_VALUE) {
        return NULL;
    }

    // 将映射视图连接到内存区域
    void* lpBaseAddress = MapViewOfFile(
        hMapFile,
        FILE_MAP_ALL_ACCESS,
        0,
        0,
        cbData
    );

    if (lpBaseAddress == NULL) {
        CloseHandle(hMapFile);
        return NULL;
    }

    // 从映射视图复制数据到内存中
    memcpy(lpBaseAddress, lpData, cbData);

    // 加载内存中的DLL
    hModule = LoadLibraryEx(
        lpBaseAddress,
        NULL,
        DONT_RESOLVE_DLL_REFERENCES | LOAD_LIBRARY_AS_DATAFILE
    );

    // 解除映射视图和关闭映射文件句柄
    UnmapViewOfFile(lpBaseAddress);
    CloseHandle(hMapFile);

    return hModule;
}

// 获取函数指针的函数实现
FARPROC GetProcAddress(HMODULE hModule, LPCSTR lpProcName) {
    // 使用GetProcAddress获取函数地址
    return GetProcAddress(hModule, lpProcName);
}
```

这段代码定义了两个函数：`LoadLibraryFromMemory` 和 `GetProcAddress`。`LoadLibraryFromMemory` 函数从指定路径的DLL文件中读取数据到内存，然后使用 `LoadLibraryEx` 从内存加载DLL。`GetProcAddress` 函数用于获取在内存中加载的DLL中的特定函数地址。

