# 加密函数，这里使用非常简单的替换加密作为例子
def encrypt_string(s):
    key = ''.join(random.choices(string.ascii_letters + string.digits, k=len(s)))
    encrypted = ''
    for i in range(len(s)):
        encrypted += chr((ord(s[i]) - 97 + ord(key[i])) % 26 + 97)
    return key, encrypted

# 解密函数
def decrypt_string(encrypted, key):
    decrypted = ''
    for i in range(len(encrypted)):
        decrypted += chr((ord(encrypted[i]) - 97 - ord(key[i])) % 26 + 97)
    return decrypted

# 混淆器类
class Obfuscator:
    def __init__(self):
        self.key_mapping = {}

    # 添加键值对到混淆映射
    def add_key_value_pair(self, original, replacement):
        if original not in self.key_mapping.values():
            self.key_mapping[replacement] = original

    # 代码等价变换函数
    def code_equivalence_transformation(self, code):
        new_code = ''
        variables = [var for var in code.split() if var.isidentifier()]
        for var in variables:
            replacement = chr(random.randint(65, 90)) + ''.join(chr(random.randint(97, 122)) for _ in range(3))
            self.add_key_value_pair(var, replacement)
            new_code += replacement + ' '
        return new_code.strip()

    # 控制流扁平化函数
    def control_flow_flattening(self, code):
        lines = code.split('\n')
        flat_code = ''
        for line in lines:
            if '{' in line:
                nested_level = 1
                while nested_level > 0:
                    flat_code += line + '\n'
                    if '{' in line:
                        nested_level += 1
                    elif '}' in line:
                        nested_level -= 1
                line = ''
            elif '}' in line and ':' not in line:
                flat_code += line.replace('}', '} }')
            else:
                flat_code += line + '\n'
        return flat_code.strip()

    # 字符串加密函数
    def encrypt_strings(self, code):
        encrypted_code = ''
        for line in code.split('\n'):
            encrypted_lines = []
            for part in line.split():
                if part.startswith('"') and part.endswith('"'):
                    key, encrypted_part = encrypt_string(part[1:-1])
                    self.key_mapping[key] = part[1:-1]
                    encrypted_lines.append(f'"{encrypted_part}"')
                else:
                    encrypted_lines.append(part)
            encrypted_code += ' '.join(encrypted_lines) + '\n'
        return encrypted_code.strip()

    # 混淆代码
    def obfuscate(self, code):
        code = self.code_equivalence_transformation(code)
        code = self.control_flow_flattening(code)
        code = self.encrypt_strings(code)
        return code

