```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract DecentralizedControlFramework {
    // 定义一个事件，用于记录指令的变化
    event C2InstructionChanged(bytes32 instruction, bool isAdded);

    // 定义一个结构来存储C2指令
    struct C2Instruction {
        bytes32 content;
        bool isActive;
    }

    // 存储所有C2指令的映射
    mapping(bytes32 => C2Instruction) public instructions;

    // 多签名控制器地址列表和阈值
    address[] public controllers;
    uint256 public controllerThreshold;

    // 控制器权限映射
    mapping(address => bool) public isController;

    // 构造函数：初始化合约
    constructor(address[] memory _controllers, uint256 _controllerThreshold) {
        require(_controllers.length >= _controllerThreshold, "Invalid threshold");
        for (uint256 i = 0; i < _controllers.length; i++) {
            require(!isController[_controllers[i]], "Duplicate controller");
            isController[_controllers[i]] = true;
        }
        controllers = _controllers;
        controllerThreshold = _controllerThreshold;
    }

    // 添加或更新C2指令
    function addOrUpdateC2Instruction(bytes32 _instruction, bool _isActive) public {
        require(isController(msg.sender), "Unauthorized access");
        instructions[_instruction].content = _instruction;
        instructions[_instruction].isActive = _isActive;

        emit C2InstructionChanged(_instruction, _isActive);
    }

    // 删除C2指令
    function deleteC2Instruction(bytes32 _instruction) public {
        require(isController(msg.sender), "Unauthorized access");
        delete instructions[_instruction];
    }
}
```

